// Android icons for native menus. @react-native-menu/menu resolves `image` as
// a drawable resource on Android (PopupMenu), so every SF Symbol used in a
// NativeMenu action maps to a Material Symbols drawable here. The XMLs live
// in assets/android-menu-icons/ (generated by
// scripts/generate-android-menu-icons.mjs) and land in res/drawable through
// plugins/withAndroidMenuIcons.js at prebuild. A new SF Symbol in a menu
// needs an entry here, then the script and a native Android build.

import type { SFSymbol } from "sf-symbols-typescript";

/** Drawable names start with `menu_` + the Material Symbols name. */
const ANDROID_MENU_ICONS: Readonly<Partial<Record<SFSymbol, string>>> = {
  // Actions
  trash: "menu_delete",
  pencil: "menu_edit",
  "square.and.pencil": "menu_edit_square",
  "plus.circle": "menu_add_circle",
  "plus.square.on.square": "menu_content_copy",
  "minus.circle": "menu_do_not_disturb_on",
  "wand.and.stars": "menu_auto_fix_high",
  pin: "menu_keep",
  "pin.slash": "menu_keep_off",
  target: "menu_target",
  "checkmark.seal": "menu_verified",
  "checkmark.circle": "menu_check_circle",
  "mappin.and.ellipse": "menu_location_on",
  "doc.richtext": "menu_article",
  "list.number": "menu_format_list_numbered",
  // Appearance and language
  "circle.lefthalf.filled": "menu_contrast",
  "sun.max": "menu_light_mode",
  moon: "menu_dark_mode",
  globe: "menu_language",
  "d.circle": "menu_letter_d",
  "e.circle": "menu_letter_e",
  // Subject fields (custom subject)
  "character.book.closed": "menu_dictionary",
  "person.3": "menu_groups",
  atom: "menu_science",
  "book.closed": "menu_book",
  "figure.run": "menu_directions_run",
  "square.grid.2x2": "menu_grid_view",
  // Subjects (src/components/ui/subjects.ts, catalog symbols)
  "text.book.closed": "menu_menu_book",
  "x.squareroot": "menu_function",
  function: "menu_function",
  "character.bubble": "menu_translate",
  scroll: "menu_history_edu",
  leaf: "menu_eco",
  "testtube.2": "menu_labs",
  "chevron.left.forwardslash.chevron.right": "menu_code",
  hourglass: "menu_hourglass",
  "globe.europe.africa": "menu_public",
  "building.columns": "menu_account_balance",
  "chart.line.uptrend.xyaxis": "menu_show_chart",
  sparkles: "menu_auto_awesome",
  "brain.head.profile": "menu_psychology",
  paintpalette: "menu_palette",
  "music.note": "menu_music_note",
  theatermasks: "menu_theater_comedy",
  "doc.text.magnifyingglass": "menu_find_in_page",
  map: "menu_map",
};

/** Android drawable name for an SF Symbol of a menu action. */
export function androidMenuIcon(sf: string | undefined): string | undefined {
  if (sf === undefined) return undefined;
  return ANDROID_MENU_ICONS[sf as SFSymbol];
}
